        "                    \"ionq_qpu\", \"qpu\",\n",
        "                    \"ionq_simulator\", \"simulator\"\n",
        "                ]\n",
        "                for target in preferred_targets:\n",
        "                    if target in available:\n",
        "                        self.backend = provider.get_backend(target)\n",
        "                        self.is_qpu = \"qpu\" in target\n",
        "                        print(f\"🎯 Connected to Target: {self.backend.name()} (Hardware: {self.is_qpu})\")\n",
        "                        return\n",
        "            except Exception as e:\n",
        "                print(f\"⚠️ Provider error: {e}. Falling back to simulation.\")\n",
        "\n",
        "        self.backend = AerSimulator()\n",
        "        self.is_qpu = False\n",
