        "# =====================================================================\n",
        "# UNIFIED QUANTUM PIPELINE — MODULES 0 → 10\n",
        "# =====================================================================\n",
        "#\n",
        "# MODULE 0  : Clean environment / dependencies\n",
        "# MODULE 1  : Secrets\n",
        "# MODULE 2  : Backend discovery + routing\n",
        "# MODULE 3  : Bell-state baseline circuit\n",
        "# MODULE 4  : Ideal local reference\n",
        "# MODULE 5  : Noisy local reference\n",
        "# MODULE 6  : CHSH circuit generation\n",
        "# MODULE 7  : IonQ execution layer\n",
        "# MODULE 8  : Job recovery\n",
        "# MODULE 9  : Raw-data integrity / archival\n",
        "# MODULE 10 : Scientific analysis + error-correction handoff\n",
        "#\n",
        "# IMPORTANT:\n",
        "#   - No API keys are hard-coded.\n",
        "#   - No PennyLane/Cirq/Braket/PySCF is installed here.\n",
        "#   - No automatic QPU submission unless RUN_IONQ_QPU = True.\n",
        "#   - Raw data are preserved separately from derived metrics.\n",
        "#\n",
        "# =====================================================================\n",
        "\n",
        "\n",
        "# =====================================================================\n",
        "# MODULE 0 — CLEAN ENVIRONMENT\n",
        "# =====================================================================\n",
        "\n",
        "print(\"=\" * 78)\n",
        "print(\"MODULE 0 — CLEAN ENVIRONMENT\")\n",
        "print(\"=\" * 78)\n",
        "\n",
        "# Qiskit-IonQ 1.1.1 is compatible with Qiskit 2.x.\n",
        "# We keep this cell Qiskit-only to avoid unnecessary dependency collisions.\n",
        "\n",
        "import sys\n",
        "import subprocess\n",
        "import importlib.util\n",
        "\n",
        "REQUIRED_PACKAGES = {\n",
        "    \"qiskit\": \"qiskit==2.4.1\",\n",
        "    \"qiskit_ionq\": \"qiskit-ionq==1.1.1\",\n",
        "    \"qiskit_aer\": \"qiskit-aer==0.17.2\",\n",
        "}\n",
        "\n",
        "missing = [\n",
        "    package\n",
        "    for package, requirement in REQUIRED_PACKAGES.items()\n",
        "    if importlib.util.find_spec(package) is None\n",
        "]\n",
        "\n",
        "if missing:\n",
        "    print(\"Installing missing quantum packages...\")\n",
        "    requirements = [\n",
        "        REQUIRED_PACKAGES[p]\n",
        "        for p in missing\n",
        "    ]\n",
        "\n",
        "    subprocess.check_call([\n",
        "        sys.executable,\n",
        "        \"-m\",\n",
        "        \"pip\",\n",
        "        \"install\",\n",
        "        \"-q\",\n",
        "        *requirements\n",
        "    ])\n",
        "\n",
        "    print(\"✅ Dependencies installed.\")\n",
        "    print(\"If Colab requests a runtime restart, restart once and rerun this cell.\")\n",
        "else:\n",
        "    print(\"✅ Required quantum packages already available.\")\n",
        "\n",
        "\n",
        "# =====================================================================\n",
        "# IMPORTS\n",
        "# =====================================================================\n",
        "\n",
        "import os\n",
        "import json\n",
        "import time\n",
        "import math\n",
        "import pickle\n",
        "import platform\n",
        "from pathlib import Path\n",
        "from datetime import datetime, timezone\n",
        "\n",
        "import numpy as np\n",
        "\n",
        "from qiskit import QuantumCircuit, transpile\n",
        "\n",
        "from qiskit_aer import AerSimulator\n",
        "\n",
        "try:\n",
        "    from qiskit_aer.noise import NoiseModel, depolarizing_error\n",
        "    AER_NOISE_AVAILABLE = True\n",
        "except Exception:\n",
        "    AER_NOISE_AVAILABLE = False\n",
        "\n",
        "try:\n",
        "    from qiskit_ionq import IonQProvider\n",
        "    IONQ_SDK_AVAILABLE = True\n",
        "except Exception:\n",
        "    IONQ_SDK_AVAILABLE = False\n",
        "\n",
        "\n",
        "print(f\"Python          : {platform.python_version()}\")\n",
        "\n",
        "try:\n",
        "    import qiskit\n",
        "    print(f\"Qiskit          : {qiskit.__version__}\")\n",
        "except Exception:\n",
        "    print(\"Qiskit version  : unavailable\")\n",
        "\n",
        "print(f\"IonQ SDK loaded : {IONQ_SDK_AVAILABLE}\")\n",
        "print(f\"Aer noise       : {AER_NOISE_AVAILABLE}\")\n",
        "\n",
        "\n",
        "# =====================================================================\n",
        "# GLOBAL CONTROL SWITCHES\n",
        "# =====================================================================\n",
        "#\n",
        "# CHANGE ONLY THESE VALUES.\n",
        "#\n",
        "# RUN_IONQ_QPU = False\n",
        "#     Safe mode. Nothing is submitted to physical hardware.\n",
        "#\n",
        "# RUN_IONQ_QPU = True\n",
        "#     Allows the pipeline to submit to an available IonQ QPU.\n",
        "#\n",
        "# RUN_IONQ_SIMULATOR = False\n",
        "#     Local simulation remains the default.\n",
        "#\n",
        "# =====================================================================\n",
        "\n",
        "RUN_IONQ_QPU = False\n",
        "RUN_IONQ_SIMULATOR = False\n",
        "\n",
        "SHOTS = 1024\n",
        "\n",
        "# QPU preference.\n",
        "# The pipeline discovers what your account actually exposes.\n",
        "QPU_PREFERENCE = [\n",
        "    \"qpu.forte-1\",\n",
        "    \"ionq_qpu.forte-1\",\n",
        "    \"qpu.forte-enterprise-1\",\n",
        "    \"ionq_qpu.forte-enterprise-1\",\n",
        "    \"qpu.aria-1\",\n",
        "    \"ionq_qpu.aria-1\",\n",
        "]\n",
        "\n",
        "SIMULATOR_PREFERENCE = [\n",
        "    \"simulator\",\n",
        "    \"ionq_simulator\",\n",
        "]\n",
        "\n",
        "LOCAL_BACKEND_NAME = \"AerSimulator\"\n",
        "\n",
        "\n",
        "# =====================================================================\n",
        "# MODULE 1 — SECRET RESOLUTION\n",
        "# =====================================================================\n",
        "\n",
        "print(\"\\n\" + \"=\" * 78)\n",
        "print(\"MODULE 1 — SECRET RESOLUTION\")\n",
        "print(\"=\" * 78)\n",
        "\n",
        "\n",
        "def resolve_ionq_api_key():\n",
        "    \"\"\"\n",
        "    Search Colab Secrets first, then environment variables.\n",
        "\n",
        "    No API key is printed.\n",
        "    Only the secret-name source is reported.\n",
        "    \"\"\"\n",
        "\n",
        "    secret_names = [\n",
        "        \"IONQ_API_KEY\",\n",
        "        \"IONQ_API_TOKEN\",\n",
        "        \"QISKIT_IONQ_API_TOKEN\",\n",
        "        \"ionq\",\n",
        "        \"ionq2\",\n",
        "        \"ionq_3\",\n",
        "        \"forte\",\n",
        "        \"aria1\",\n",
        "    ]\n",
        "\n",
        "    # ---------------------------------------------------------------\n",
        "    # Google Colab Secret Manager\n",
        "    # ---------------------------------------------------------------\n",
        "\n",
        "    try:\n",
        "        from google.colab import userdata\n",
        "\n",
        "        for name in secret_names:\n",
        "            try:\n",
        "                value = userdata.get(name)\n",
        "\n",
        "                if value is not None:\n",
        "                    value = str(value).strip()\n",
        "\n",
        "                    if len(value) > 5:\n",
        "                        print(\n",
        "                            f\"🔑 IonQ credential found in Colab Secret: {name}\"\n",
        "                        )\n",
        "                        return value\n",
        "\n",
        "            except Exception:\n",
        "                continue\n",
        "\n",
        "    except Exception:\n",
        "        pass\n",
        "\n",
        "    # ---------------------------------------------------------------\n",
        "    # Environment variables\n",
        "    # ---------------------------------------------------------------\n",
        "\n",
        "    for name in secret_names:\n",
        "\n",
        "        value = os.getenv(name)\n",
        "\n",
        "        if value:\n",
        "            value = value.strip()\n",
        "\n",
        "            if len(value) > 5:\n",
        "                print(\n",
        "                    f\"🔑 IonQ credential found in environment: {name}\"\n",
        "                )\n",
        "                return value\n",
        "\n",
        "    print(\"⚠️ No IonQ API key detected.\")\n",
        "    print(\"   Local simulation remains available.\")\n",
        "\n",
        "    return None\n",
        "\n",
        "\n",
        "IONQ_API_KEY = resolve_ionq_api_key()\n",
        "\n",
        "\n",
        "# =====================================================================\n",
        "# MODULE 2 — BACKEND DISCOVERY + ROUTING\n",
        "# =====================================================================\n",
        "\n",
        "print(\"\\n\" + \"=\" * 78)\n",
        "print(\"MODULE 2 — BACKEND DISCOVERY + ROUTING\")\n",
        "print(\"=\" * 78)\n",
        "\n",
        "\n",
        "def backend_name(backend):\n",
        "    \"\"\"\n",
        "    Handle backend.name whether it is a property or callable.\n",
        "    \"\"\"\n",
        "\n",
        "    try:\n",
        "        value = backend.name\n",
        "\n",
        "        if callable(value):\n",
        "            value = value()\n",
        "\n",
        "        return str(value)\n",
        "\n",
        "    except Exception:\n",
        "        return str(backend)\n",
        "\n",
        "\n",
        "class QuantumRouter:\n",
        "\n",
        "    def __init__(self, api_key=None):\n",
        "\n",
        "        self.api_key = api_key\n",
        "\n",
        "        self.provider = None\n",
        "\n",
        "        self.qpu_backend = None\n",
        "        self.simulator_backend = None\n",
        "        self.local_backend = AerSimulator()\n",
        "\n",
        "        self.qpu_available = False\n",
        "        self.ionq_sim_available = False\n",
        "\n",
        "        self.discover()\n",
        "\n",
        "    # ---------------------------------------------------------------\n",
        "\n",
        "    def discover(self):\n",
        "\n",
        "        print(\"\\n🔎 Discovering available backends...\")\n",
        "\n",
        "        if not IONQ_SDK_AVAILABLE:\n",
        "            print(\"⚠️ qiskit-ionq is unavailable.\")\n",
        "            return\n",
        "\n",
        "        if not self.api_key:\n",
        "            print(\"⚠️ No API key — remote IonQ discovery skipped.\")\n",
        "            return\n",
        "\n",
        "        try:\n",
        "\n",
        "            self.provider = IonQProvider(token=self.api_key)\n",
        "\n",
        "            backends = list(self.provider.backends())\n",
        "\n",
        "            names = [\n",
        "                backend_name(b)\n",
        "                for b in backends\n",
        "            ]\n",
        "\n",
        "            print(\"IonQ-visible backends:\")\n",
        "            for name in names:\n",
        "                print(f\"   • {name}\")\n",
        "\n",
        "            # -------------------------------------------------------\n",
        "            # Find QPU\n",
        "            # -------------------------------------------------------\n",
        "\n",
        "            for preferred in QPU_PREFERENCE:\n",
        "\n",
        "                if preferred in names:\n",
        "\n",
        "                    self.qpu_backend = self.provider.get_backend(\n",
        "                        preferred\n",
        "                    )\n",
        "\n",
        "                    self.qpu_available = True\n",
        "\n",
        "                    print(\n",
        "                        f\"✅ QPU candidate: {preferred}\"\n",
        "                    )\n",
        "\n",
        "                    break\n",
        "\n",
        "            # -------------------------------------------------------\n",
        "            # Find IonQ simulator\n",
        "            # -------------------------------------------------------\n",
        "\n",
        "            for preferred in SIMULATOR_PREFERENCE:\n",
        "\n",
        "                if preferred in names:\n",
        "\n",
        "                    self.simulator_backend = (\n",
        "                        self.provider.get_backend(preferred)\n",
        "                    )\n",
        "\n",
        "                    self.ionq_sim_available = True\n",
        "\n",
        "                    print(\n",
        "                        f\"✅ IonQ simulator candidate: {preferred}\"\n",
        "                    )\n",
        "\n",
        "                    break\n",
        "\n",
        "        except Exception as exc:\n",
        "\n",
        "            print(\n",
        "                f\"⚠️ IonQ backend discovery failed: {exc}\"\n",
        "            )\n",
        "\n",
        "    # ---------------------------------------------------------------\n",
        "\n",
        "    def summary(self):\n",
        "\n",
        "        print(\"\\nBACKEND SUMMARY\")\n",
        "        print(\"-\" * 60)\n",
        "\n",
        "        if self.qpu_backend:\n",
        "\n",
        "            print(\n",
        "                f\"Physical QPU : \"\n",
        "                f\"{backend_name(self.qpu_backend)}\"\n",
        "            )\n",
        "\n",
        "        else:\n",
        "\n",
        "            print(\"Physical QPU : NOT AVAILABLE\")\n",
        "\n",
        "        if self.simulator_backend:\n",
        "\n",
        "            print(\n",
        "                f\"IonQ simulator : \"\n",
        "                f\"{backend_name(self.simulator_backend)}\"\n",
        "            )\n",
        "\n",
        "        else:\n",
        "\n",
        "            print(\"IonQ simulator : NOT AVAILABLE\")\n",
        "\n",
        "        print(\n",
        "            f\"Local simulator: {LOCAL_BACKEND_NAME}\"\n",
        "        )\n",
        "\n",
        "\n",
        "router = QuantumRouter(IONQ_API_KEY)\n",
        "\n",
        "router.summary()\n",
        "\n",
        "\n",
        "# =====================================================================\n",
        "# MODULE 3 — BELL-STATE BASELINE CIRCUIT\n",
        "# =====================================================================\n",
        "\n",
        "print(\"\\n\" + \"=\" * 78)\n",
        "print(\"MODULE 3 — BELL-STATE BASELINE\")\n",
        "print(\"=\" * 78)\n",
        "\n",
        "\n",
        "def build_bell_baseline():\n",
        "\n",
        "    qc = QuantumCircuit(\n",
        "        2,\n",
        "        2,\n",
        "        name=\"Bell_Baseline\"\n",
        "    )\n",
        "\n",
        "    # Bell-state preparation\n",
        "    qc.h(0)\n",
        "    qc.cx(0, 1)\n",
        "\n",
        "    qc.measure(\n",
        "        [0, 1],\n",
        "        [0, 1]\n",
        "    )\n",
        "\n",
        "    return qc\n",
        "\n",
        "\n",
        "bell_circuit = build_bell_baseline()\n",
        "\n",
        "print(bell_circuit)\n",
        "\n",
        "\n",
        "# =====================================================================\n",
        "# MODULE 4 — IDEAL LOCAL REFERENCE\n",
        "# =====================================================================\n",
        "\n",
        "print(\"\\n\" + \"=\" * 78)\n",
        "print(\"MODULE 4 — IDEAL LOCAL REFERENCE\")\n",
        "print(\"=\" * 78)\n",
        "\n",
        "\n",
        "def run_local_ideal(circuit, shots=SHOTS):\n",
        "\n",
        "    simulator = AerSimulator()\n",
        "\n",
        "    compiled = transpile(\n",
        "        circuit,\n",
        "        simulator,\n",
        "        optimization_level=1\n",
        "    )\n",
        "\n",
        "    job = simulator.run(\n",
        "        compiled,\n",
        "        shots=shots,\n",
        "        memory=True\n",
        "    )\n",
        "\n",
        "    result = job.result()\n",
        "\n",
        "    return {\n",
        "        \"backend\": LOCAL_BACKEND_NAME,\n",
        "        \"execution_class\": \"LOCAL_IDEAL\",\n",
        "        \"counts\": result.get_counts(),\n",
        "        \"memory\": job.get_memory(),\n",
        "        \"shots\": shots,\n",
        "        \"job_id\": \"local_ideal\",\n",
        "    }\n",
        "\n",
        "\n",
        "ideal_result = run_local_ideal(\n",
        "    bell_circuit,\n",
        "    SHOTS\n",
        ")\n",
        "\n",
        "print(\"Ideal reference counts:\")\n",
        "print(ideal_result[\"counts\"])\n",
        "\n",
        "\n",
        "# =====================================================================\n",
        "# MODULE 5 — LOCAL NOISY REFERENCE\n",
        "# =====================================================================\n",
        "\n",
        "print(\"\\n\" + \"=\" * 78)\n",
        "print(\"MODULE 5 — LOCAL NOISY REFERENCE\")\n",
        "print(\"=\" * 78)\n",
        "\n",
        "\n",
        "def build_local_noise_model():\n",
        "\n",
        "    if not AER_NOISE_AVAILABLE:\n",
        "\n",
        "        return None\n",
        "\n",
        "    noise = NoiseModel()\n",
        "\n",
        "    # Conservative generic reference model.\n",
        "    #\n",
        "    # IMPORTANT:\n",
        "    # These are NOT IonQ published hardware parameters.\n",
        "    #\n",
        "    # This is only a generic local noisy reference.\n",
        "    #\n",
        "    # Actual IonQ noise characterization is kept separate.\n",
        "\n",
        "    one_qubit_error = depolarizing_error(\n",
        "        0.001,\n",
        "        1\n",
        "    )\n",
        "\n",
        "    two_qubit_error = depolarizing_error(\n",
        "        0.01,\n",
        "        2\n",
        "    )\n",
        "\n",
        "    noise.add_all_qubit_quantum_error(\n",
        "        one_qubit_error,\n",
        "        [\n",
        "            \"h\",\n",
        "            \"x\",\n",
        "            \"y\",\n",
        "            \"z\",\n",
        "            \"rx\",\n",
        "            \"ry\",\n",
        "            \"rz\",\n",
        "            \"sx\",\n",
        "        ]\n",
        "    )\n",
        "\n",
        "    noise.add_all_qubit_quantum_error(\n",
        "        two_qubit_error,\n",
        "        [\n",
        "            \"cx\"\n",
        "        ]\n",
        "    )\n",
        "\n",
        "    return noise\n",
        "\n",
        "\n",
        "def run_local_noisy(circuit, shots=SHOTS):\n",
        "\n",
        "    if not AER_NOISE_AVAILABLE:\n",
        "\n",
        "        print(\n",
        "            \"⚠️ Aer noise module unavailable.\"\n",
        "        )\n",
        "\n",
        "        return None\n",
        "\n",
        "    noise_model = build_local_noise_model()\n",
        "\n",
        "    simulator = AerSimulator(\n",
        "        noise_model=noise_model\n",
        "    )\n",
        "\n",
        "    compiled = transpile(\n",
        "        circuit,\n",
        "        simulator,\n",
        "        optimization_level=1\n",
        "    )\n",
        "\n",
        "    job = simulator.run(\n",
        "        compiled,\n",
        "        shots=shots,\n",
        "        memory=True\n",
        "    )\n",
        "\n",
        "    result = job.result()\n",
        "\n",
        "    return {\n",
        "        \"backend\": LOCAL_BACKEND_NAME,\n",
        "        \"execution_class\": \"LOCAL_GENERIC_NOISY\",\n",
        "        \"counts\": result.get_counts(),\n",
        "        \"memory\": job.get_memory(),\n",
        "        \"shots\": shots,\n",
        "        \"job_id\": \"local_noisy\",\n",
        "    }\n",
        "\n",
        "\n",
        "noisy_result = run_local_noisy(\n",
        "    bell_circuit,\n",
        "    SHOTS\n",
        ")\n",
        "\n",
        "if noisy_result:\n",
        "\n",
        "    print(\n",
        "        \"Generic noisy-reference counts:\"\n",
        "    )\n",
        "\n",
        "    print(\n",
        "        noisy_result[\"counts\"]\n",
        "    )\n",
        "\n",
        "\n",
        "# =====================================================================\n",
        "# MODULE 6 — CHSH CIRCUIT GENERATION\n",
        "# =====================================================================\n",
        "#\n",
        "# CHSH settings:\n",
        "#\n",
        "# Alice:\n",
        "#   A0 = Z\n",
        "#   A1 = X\n",
        "#\n",
        "# Bob:\n",
        "#   B0 = (Z + X) / sqrt(2)\n",
        "#   B1 = (Z - X) / sqrt(2)\n",
        "#\n",
        "# S = E(A0,B0) + E(A0,B1)\n",
        "#     + E(A1,B0) - E(A1,B1)\n",
        "#\n",
        "# Ideal |Phi+> produces |S| = 2*sqrt(2).\n",
        "#\n",
        "# A value greater than 2 is the Bell-inequality violation region.\n",
        "#\n",
        "# =====================================================================\n",
        "\n",
        "print(\"\\n\" + \"=\" * 78)\n",
        "print(\"MODULE 6 — CHSH CIRCUIT GENERATION\")\n",
        "print(\"=\" * 78)\n",
        "\n",
        "\n",
        "CHSH_SETTINGS = {\n",
        "    \"A0_B0\": (\"Z\", \"+45\"),\n",
        "    \"A0_B1\": (\"Z\", \"-45\"),\n",
        "    \"A1_B0\": (\"X\", \"+45\"),\n",
        "    \"A1_B1\": (\"X\", \"-45\"),\n",
        "}\n",
        "\n",
        "\n",
        "def prepare_bell(qc):\n",
        "\n",
        "    qc.h(0)\n",
        "    qc.cx(0, 1)\n",
        "\n",
        "\n",
        "def apply_measurement_basis(\n",
        "    qc,\n",
        "    alice_basis,\n",
        "    bob_basis\n",
        "):\n",
        "\n",
        "    # ---------------------------------------------------------------\n",
        "    # Alice\n",
        "    # ---------------------------------------------------------------\n",
        "\n",
        "    if alice_basis == \"X\":\n",
        "\n",
        "        qc.h(0)\n",
        "\n",
        "    elif alice_basis != \"Z\":\n",
        "\n",
        "        raise ValueError(\n",
        "            f\"Unknown Alice basis: {alice_basis}\"\n",
        "        )\n",
        "\n",
        "    # ---------------------------------------------------------------\n",
        "    # Bob\n",
        "    # ---------------------------------------------------------------\n",
        "    #\n",
        "    # To measure along an axis\n",
        "    #\n",
        "    # cos(theta) Z + sin(theta) X\n",
        "    #\n",
        "    # apply RY(-theta), then measure Z.\n",
        "    #\n",
        "    # +45° -> (Z + X)/sqrt(2)\n",
        "    # -45° -> (Z - X)/sqrt(2)\n",
        "    #\n",
        "    # ---------------------------------------------------------------\n",
        "\n",
        "    if bob_basis == \"+45\":\n",
        "\n",
        "        qc.ry(\n",
        "            -math.pi / 4,\n",
        "            1\n",
        "        )\n",
        "\n",
        "    elif bob_basis == \"-45\":\n",
        "\n",
        "        qc.ry(\n",
        "            +math.pi / 4,\n",
        "            1\n",
        "        )\n",
        "\n",
        "    else:\n",
        "\n",
        "        raise ValueError(\n",
        "            f\"Unknown Bob basis: {bob_basis}\"\n",
        "        )\n",
        "\n",
        "\n",
        "def build_chsh_circuit(\n",
        "    alice_basis,\n",
        "    bob_basis,\n",
        "    name\n",
        "):\n",
        "\n",
        "    qc = QuantumCircuit(\n",
        "        2,\n",
        "        2,\n",
        "        name=name\n",
        "    )\n",
        "\n",
        "    prepare_bell(qc)\n",
        "\n",
        "    apply_measurement_basis(\n",
        "        qc,\n",
        "        alice_basis,\n",
        "        bob_basis\n",
        "    )\n",
        "\n",
        "    qc.measure(\n",
        "        [0, 1],\n",
        "        [0, 1]\n",
        "    )\n",
        "\n",
        "    return qc\n",
        "\n",
        "\n",
        "chsh_circuits = {}\n",
        "\n",
        "for setting, (alice, bob) in CHSH_SETTINGS.items():\n",
        "\n",
        "    chsh_circuits[setting] = build_chsh_circuit(\n",
        "        alice,\n",
        "        bob,\n",
        "        setting\n",
        "    )\n",
        "\n",
        "    print(\n",
        "        f\"\\n--- {setting} ---\"\n",
        "    )\n",
        "\n",
        "    print(\n",
        "        chsh_circuits[setting]\n",
        "    )\n",
        "\n",
        "\n",
        "# =====================================================================\n",
        "# MODULE 7 — UNIFIED EXECUTION ENGINE\n",
        "# =====================================================================\n",
        "\n",
        "print(\"\\n\" + \"=\" * 78)\n",
        "print(\"MODULE 7 — UNIFIED EXECUTION ENGINE\")\n",
        "print(\"=\" * 78)\n",
        "\n",
        "\n",
        "def run_local(\n",
        "    circuit,\n",
        "    shots=SHOTS\n",
        "):\n",
        "\n",
        "    simulator = AerSimulator()\n",
        "\n",
        "    compiled = transpile(\n",
        "        circuit,\n",
        "        simulator,\n",
        "        optimization_level=1\n",
        "    )\n",
        "\n",
        "    job = simulator.run(\n",
        "        compiled,\n",
        "        shots=shots,\n",
        "        memory=True\n",
        "    )\n",
        "\n",
        "    result = job.result()\n",
        "\n",
        "    return {\n",
        "        \"job_id\": \"local_aer\",\n",
        "        \"backend\": LOCAL_BACKEND_NAME,\n",
        "        \"execution_class\": \"LOCAL_IDEAL\",\n",
        "        \"is_qpu\": False,\n",
        "        \"counts\": result.get_counts(),\n",
        "        \"memory\": job.get_memory(),\n",
        "        \"shots\": shots,\n",
        "        \"timestamp\": time.time(),\n",
        "    }\n",
        "\n",
        "\n",
        "def run_ionq_simulator(\n",
        "    circuit,\n",
        "    shots=SHOTS,\n",
        "    noise_model=None\n",
        "):\n",
        "\n",
        "    if not router.ionq_sim_available:\n",
        "\n",
        "        raise RuntimeError(\n",
        "            \"IonQ simulator is not available.\"\n",
        "        )\n",
        "\n",
        "    backend = router.simulator_backend\n",
        "\n",
        "    if noise_model:\n",
        "\n",
        "        try:\n",
        "\n",
        "            backend.set_options(\n",
        "                noise_model=noise_model\n",
        "            )\n",
        "\n",
        "            print(\n",
        "                f\"Using IonQ noise model: {noise_model}\"\n",
        "            )\n",
        "\n",
        "        except Exception as exc:\n",
        "\n",
        "            print(\n",
        "                f\"⚠️ Could not set IonQ noise model: {exc}\"\n",
        "            )\n",
        "\n",
        "    job = backend.run(\n",
        "        circuit,\n",
        "        shots=shots,\n",
        "        memory=True\n",
        "    )\n",
        "\n",
        "    result = job.result()\n",
        "\n",
        "    try:\n",
        "        memory = job.get_memory()\n",
        "    except Exception:\n",
        "        memory = []\n",
        "\n",
        "    return {\n",
        "        \"job_id\": job.job_id(),\n",
        "        \"backend\": backend_name(backend),\n",
        "        \"execution_class\": (\n",
        "            \"IONQ_CLOUD_NOISY_SIMULATOR\"\n",
        "            if noise_model\n",
        "            else \"IONQ_CLOUD_IDEAL_SIMULATOR\"\n",
        "        ),\n",
        "        \"is_qpu\": False,\n",
        "        \"counts\": result.get_counts(),\n",
        "        \"memory\": memory,\n",
        "        \"shots\": shots,\n",
        "        \"timestamp\": time.time(),\n",
        "    }\n",
        "\n",
        "\n",
        "def run_ionq_qpu(\n",
        "    circuit,\n",
        "    shots=SHOTS,\n",
        "    debiasing=True\n",
        "):\n",
        "\n",
        "    if not router.qpu_available:\n",
        "\n",
        "        raise RuntimeError(\n",
        "            \"No accessible IonQ QPU was discovered.\"\n",
        "        )\n",
        "\n",
        "    backend = router.qpu_backend\n",
        "\n",
        "    print(\n",
        "        \"\\n🚨 PHYSICAL IONQ QPU SUBMISSION\"\n",
        "    )\n",
        "\n",
        "    print(\n",
        "        f\"Backend: {backend_name(backend)}\"\n",
        "    )\n",
        "\n",
        "    # ---------------------------------------------------------------\n",
        "    # IonQ's current provider supports explicit error-mitigation\n",
        "    # configuration. We try the current enum API first.\n",
        "    # ---------------------------------------------------------------\n",
        "\n",
        "    run_kwargs = {\n",
        "        \"shots\": shots,\n",
        "        \"memory\": True,\n",
        "    }\n",
        "\n",
        "    try:\n",
        "\n",
        "        from qiskit_ionq import ErrorMitigation\n",
        "\n",
        "        run_kwargs[\"error_mitigation\"] = (\n",
        "            ErrorMitigation.DEBIASING\n",
        "            if debiasing\n",
        "            else ErrorMitigation.NO_DEBIASING\n",
        "        )\n",
        "\n",
        "    except Exception:\n",
        "\n",
        "        # Compatibility fallback for older provider interfaces.\n",
        "        run_kwargs[\"debiasing\"] = debiasing\n",
        "\n",
        "    job = backend.run(\n",
        "        circuit,\n",
        "        **run_kwargs\n",
        "    )\n",
        "\n",
        "    job_id = job.job_id()\n",
        "\n",
        "    print(\n",
        "        f\"🆔 IonQ Job ID: {job_id}\"\n",
        "    )\n",
        "\n",
        "    # ---------------------------------------------------------------\n",
        "    # Save job ID immediately.\n",
        "    # ---------------------------------------------------------------\n",
        "\n",
        "    with open(\n",
        "        \"active_ionq_job.json\",\n",
        "        \"w\"\n",
        "    ) as f:\n",
        "\n",
        "        json.dump(\n",
        "            {\n",
        "                \"job_id\": job_id,\n",
        "                \"backend\": backend_name(backend),\n",
        "                \"timestamp\": time.time(),\n",
        "            },\n",
        "            f,\n",
        "            indent=2\n",
        "        )\n",
        "\n",
        "    print(\n",
        "        \"💾 Job ID saved to active_ionq_job.json\"\n",
        "    )\n",
        "\n",
        "    # ---------------------------------------------------------------\n",
        "    # Wait for completion.\n",
        "    # ---------------------------------------------------------------\n",
        "\n",
        "    while not job.done():\n",
        "\n",
        "        try:\n",
        "            status = job.status()\n",
        "            status_text = getattr(\n",
        "                status,\n",
        "                \"name\",\n",
        "                str(status)\n",
        "            )\n",
        "        except Exception:\n",
        "            status_text = \"unknown\"\n",
        "\n",
        "        print(\n",
        "            f\"⏳ IonQ status: {status_text}\"\n",
        "        )\n",
        "\n",
        "        time.sleep(20)\n",
        "\n",
        "    result = job.result()\n",
        "\n",
        "    try:\n",
        "        memory = job.get_memory()\n",
        "    except Exception:\n",
        "        memory = []\n",
        "\n",
        "    return {\n",
        "        \"job_id\": job_id,\n",
        "        \"backend\": backend_name(backend),\n",
        "        \"execution_class\": \"REAL_IONQ_QPU\",\n",
        "        \"is_qpu\": True,\n",
        "        \"counts\": result.get_counts(),\n",
        "        \"memory\": memory,\n",
        "        \"shots\": shots,\n",
        "        \"timestamp\": time.time(),\n",
        "    }\n",
        "\n",
        "\n",
        "def execute_circuit(\n",
        "    circuit,\n",
        "    shots=SHOTS,\n",
        "    allow_qpu=False\n",
        "):\n",
        "\n",
        "    # ---------------------------------------------------------------\n",
        "    # Physical QPU\n",
        "    # ---------------------------------------------------------------\n",
        "\n",
        "    if allow_qpu:\n",
        "\n",
        "        return run_ionq_qpu(\n",
        "            circuit,\n",
        "            shots=shots\n",
        "        )\n",
        "\n",
        "    # ---------------------------------------------------------------\n",
        "    # IonQ cloud simulator\n",
        "    # ---------------------------------------------------------------\n",
        "\n",
        "    if RUN_IONQ_SIMULATOR:\n",
        "\n",
        "        if router.ionq_sim_available:\n",
        "\n",
        "            return run_ionq_simulator(\n",
        "                circuit,\n",
        "                shots=shots\n",
        "            )\n",
        "\n",
        "        print(\n",
        "            \"⚠️ IonQ simulator unavailable.\"\n",
        "        )\n",
        "\n",
        "    # ---------------------------------------------------------------\n",
        "    # Local Aer\n",
        "    # ---------------------------------------------------------------\n",
        "\n",
        "    return run_local(\n",
        "        circuit,\n",
        "        shots=shots\n",
        "    )\n",
        "\n",
        "\n",
        "# =====================================================================\n",
