        "\n",
        "# 1. Provide your actual IonQ API key\n",
        "API_KEY = os.getenv(\"IONQ_API_KEY\", \"YOUR_ACTUAL_IONQ_API_KEY\")\n",
        "provider = IonQProvider(token=API_KEY)\n",
        "\n",
        "# 2. Select physical trapped-ion hardware\n",
        "# Options: 'ionq_qpu.aria-1', 'ionq_qpu.forte-1', or generic 'ionq_qpu'\n",
        "backend = provider.get_backend(\"ionq_qpu.aria-1\")\n",
        "\n",
        "# 3. Define the circuit\n",
        "qc = QuantumCircuit(2, 2)\n",
        "qc.h(0)\n",
        "qc.cx(0, 1)\n",
        "qc.measure([0, 1], [0, 1])\n",
        "\n",
        "# 4. Transpile for native IonQ gates\n",
        "transpiled_qc = transpile(qc, backend, optimization_level=1)\n",
        "\n",
        "# 5. Submit job to hardware\n",
        "# shots: number of runs; memory: returns raw bitstring per shot\n",
        "job = backend.run(transpiled_qc, shots=1000, debiasing=True, memory=True)\n",
        "job_id = job.job_id()\n",
        "print(f\"Submitted to {backend.name()}. Job ID: {job_id}\")\n",
        "\n",
        "# 6. Block and poll until execution finishes on the hardware\n",
        "while not job.done():\n",
        "    print(f\"Status: {job.status().name} (checking in 20s...)\")\n",
        "    time.sleep(20)\n",
        "\n",
        "# 7. Extract raw Python data\n",
        "result = job.result()\n",
        "raw_counts = result.get_counts()  # Dict[str, int] -> e.g. {'00': 489, '11': 495, '01': 8, '10': 8}\n",
        "raw_memory = job.get_memory()     # List[str] -> e.g. ['00', '11', '00', ...]\n",
        "\n",
        "print(\"\\n--- RAW DATA OUTPUT ---\")\n",
        "print(\"counts =\", raw_counts)\n",
        "print(\"first_10_shots =\", raw_memory[:10])\n"
