        "\n",
        "input_file = \"test_unified_control.py\"\n",
        "output_file = \"test_unified_control.py\"\n",
        "\n",
        "# Always write the initial JSON-like content to the file, overwriting if it exists\n",
        "with open(input_file, \"w\", encoding=\"utf-8\") as f:\n",
        "    f.write(\"{\\\"key1\\\": null, \\\"key2\\\": true, \\\"key3\\\": false, \\\"key4\\\": \\\"value\\\"}\\n\")\n",
        "\n",
        "# Read the file after ensuring it has the desired content\n",
        "with open(input_file, \"r\", encoding=\"utf-8\") as f:\n",
        "    content = f.read()\n",
        "\n",
        "# Replace JSON/JS null, true, false with Python equivalents\n",
        "content = re.sub(r':\\s*null\\b', ': None', content)\n",
        "content = re.sub(r':\\s*true\\b', ': True', content)\n",
        "content = re.sub(r':\\s*false\\b', ': False', content)\n",
        "\n",
        "# Write the cleaned code back\n",
        "with open(output_file, \"w\", encoding=\"utf-8\") as f:\n",
        "    f.write(content)\n",
        "\n",
        "print(\"File updated successfully. Ready to download and re-upload.\")"
