        "!pip install qiskit-ionq qiskit --quiet\n",
        "\n",
        "import os\n",
        "import sys\n",
        "from qiskit import QuantumCircuit\n",
        "from qiskit_ionq import IonQProvider\n",
        "\n",
        "# 1. 🛡️ GATEKEEPER CREDENTIAL CHECK\n",
        "# Set your IonQ API Key here or load it from Colab Secrets / Environment Variables\n",
        "IONQ_API_KEY = \"YOUR_IONQ_API_KEY\"\n",
        "\n",
        "if IONQ_API_KEY == \"YOUR_IONQ_API_KEY\" or not IONQ_API_KEY:\n",
        "    print(\"❌ [NOT ALLOWED]: Please input a valid IonQ API Key to proceed.\")\n",
        "    sys.exit()\n",
        "\n",
        "print(\"🛡️ Gatekeeper: Authentication Passed. Connecting to IonQ Cloud...\")\n",
        "provider = IonQProvider(IONQ_API_KEY)\n",
        "\n",
        "# 2. 🎛️ BACKEND CALIBRATION\n",
        "# Swap \"ionq_simulator\" to \"ionq_qpu\" when you are ready to use your credits/shots!\n",
        "backend = provider.get_backend(\"ionq_simulator\")\n",
        "print(f\"📡 Connected Backend: {backend.name()}\")\n",
        "\n",
        "# 3. 🧬 EXPERIMENT SPECIFICATION (The Nature Simulator)\n",
        "# Modeling a 2-qubit entangled singlet state for bird magnetoreception\n",
        "qc = QuantumCircuit(2, 2, name=\"Mo_Bird_Magnetoreception\")\n",
        "qc.h(0)\n",
        "qc.cx(0, 1)\n",
        "qc.measure([0, 1], [0, 1])\n",
        "\n",
        "# 4. 🚀 RUN THE LOOP WITH PREDICTIVE RESILIENCE\n",
        "try:\n",
        "    print(\"🛰️ Dispatching experiment workload to trapped-ion chain...\")\n",
        "    # 'shots' balances accuracy against budget tokens\n",
        "    job = backend.run(qc, shots=1000)\n",
        "\n",
        "    print(f\"🆔 Job Submitted Successfully! ID: {job.job_id()}\")\n",
        "    print(\"⏳ Waiting for hardware queue execution...\")\n",
        "\n",
        "    # Block and wait for results safely\n",
        "    result = job.result()\n",
        "    counts = result.get_counts()\n",
