        "# Simple consensus check: Perfect entanglement should yield mostly '00' and '11'\n",
        "error_rate = counts.get('01', 0) + counts.get('10', 0)\n",
        "total_shots = sum(counts.values())\n",
        "calculated_noise = error_rate / total_shots\n",
