        "# 1. Install the IonQ provider library in your Colab environment\n",
        "!pip install qiskit-ionq qiskit --quiet\n",
        "\n",
        "import os\n",
        "import time\n",
        "from qiskit import QuantumCircuit\n",
        "from qiskit_ionq import IonQProvider\n",
        "\n",
        "# 2. Authenticate with IonQ\n",
        "# Paste your API token from cloud.ionq.com here\n",
        "IONQ_API_KEY = \"YOUR_IONQ_API_KEY_HERE\"\n",
        "provider = IonQProvider(token=IONQ_API_KEY)\n",
        "\n",
        "# 3. Select your Target Backend\n",
        "# Use 'ionq_simulator' for free testing, or 'ionq_qpu.forte-1' for hardware\n",
        "backend = provider.get_backend('ionq_simulator')\n",
        "\n",
        "# 4. Define your Quantum Circuit (e.g., a simple 2-qubit Bell State)\n",
        "qc = QuantumCircuit(2, name=\"Colab to IonQ Job\")\n",
        "qc.h(0)\n",
        "qc.cx(0, 1)\n",
        "qc.measure_all()\n",
        "\n",
        "# 5. Submit the Job to IonQ Cloud\n",
        "print(\"🚀 Submitting job to IonQ...\")\n",
        "job = backend.run(qc, shots=1000)\n",
        "\n",
        "# CRITICAL STEP: Save this ID! If Colab disconnects, you can retrieve your data using this string.\n",
        "job_id = job.job_id()\n",
        "print(f\"✅ Job successfully submitted! Unique Job ID: {job_id}\")\n",
        "print(\"---------------------------------------------------------\")\n",
        "\n",
        "# 6. Live Status Tracker Loop\n",
        "print(\"⏳ Waiting for hardware availability / execution...\")\n",
        "while not job.done():\n",
        "    status = job.status()\n",
        "    print(f\"Current Status: {status.name} (Checking again in 20 seconds...)\")\n",
        "    time.sleep(20)\n",
