        "# 4. Define the quantum circuit\n",
        "@qml.qnode(dev)\n",
        "def entanglement_test():\n",
        "    # Prepare a Bell state (entanglement between qubit 0 and 1)\n",
        "    qml.Hadamard(wires=0)\n",
        "    qml.CNOT(wires=[0, 1])\n",
        "\n",
        "    # Return the probability distribution of the measurement outcomes\n",
        "    return qml.probs(wires=[0, 1])\n",
        "\n",
        "# 5. Execute the job and print the telemetry\n",
        "print(\"Submitting circuit job to IonQ Aria-1...\")\n",
        "probabilities = entanglement_test()\n",
