        "print(f\"Probability |01⟩: {probabilities[1]:.4f}\")\n",
        "print(f\"Probability |10⟩: {probabilities[2]:.4f}\")\n",
        "print(f\"Probability |11⟩: {probabilities[3]:.4f}\")"
