        "# Install the PennyLane IonQ plugin\n",
        "!pip install -q pennylane pennylane-ionq\n",
        "\n",
        "import pennylane as qml\n",
        "from google.colab import userdata\n",
        "\n",
        "# 1. Securely fetch your IonQ API key from Colab Secrets\n",
        "try:\n",
        "    IONQ_KEY = userdata.get('IONQ_API_KEY')\n",
        "except Exception:\n",
        "    raise ValueError(\"Please add your 'IONQ_API_KEY' to the Colab Secrets (key icon) sidebar!\")\n",
        "\n",
        "# 2. Define the number of qubits (wires) for your experiment\n",
        "num_qubits = 2\n",
        "num_shots = 1000  # Adjust your shots allocation here\n",
        "\n",
        "# 3. Initialize the IonQ physical QPU device\n",
        "# Change \"ionq.qpu\" to \"ionq.simulator\" if you want to run a dry-run test first\n",
        "dev = qml.device(\n",
        "    \"ionq.qpu\",\n",
        "    wires=num_qubits,\n",
        "    shots=num_shots,\n",
        "    api_key=IONQ_KEY\n",
        ")\n",
        "\n",
        "# 4. Define your Quantum Circuit (QNode)\n",
        "@qml.qnode(dev)\n",
        "def quantum_experiment():\n",
        "    # Example: Creating a maximally entangled Bell State (Superposition + Entanglement)\n",
        "    qml.Hadamard(wires=0)\n",
        "    qml.CNOT(wires=[0, 1])\n",
        "\n",
        "    # Return the measurement sample probabilities\n",
        "    return qml.probs(wires=range(num_qubits))\n",
        "\n",
        "# 5. Execute the job (This submits the experiment directly to IonQ's servers)\n",
        "print(\"🚀 Submitting quantum circuit job to IonQ QPU...\")\n",
