        "# Use 'wires=n' to limit the footprint\n",
        "dev = qml.device(\"default.qubit\", wires=5)\n",
        "\n",
        "# 2. Use a \"Transpile\" approach to reduce gate count\n",
        "@qml.qnode(dev)\n",
        "@qml.compile(optimizer=\"retarget\") # This automatically optimizes the circuit\n",
        "def atomic_model_circuit(params):\n",
        "    # Only map the active orbitals/electrons needed\n",
        "    qml.RY(params[0], wires=0)\n",
