        "from pennylane import numpy as np\n",
        "import csv\n",
        "\n",
        "# 1. Setup Device (Pivoting to local simulator for logic validation)\n",
        "# We use 'default.mixed' because it supports noise channels like DepolarizingChannel\n",
        "dev = qml.device(\"default.mixed\", wires=2)\n",
        "\n",
        "# 2. The Physics Engine: Thermal-Aware Quantum Circuit\n",
        "def thermal_depolarizing_channel(T, energy_gap=1.0):\n",
        "    # Mapping thermal energy to leak probability\n",
        "    return 1 - np.exp(-energy_gap / (T + 1e-6))\n",
        "\n",
        "@qml.qnode(dev)\n",
        "def get_density_matrix(T):\n",
        "    # State Preparation\n",
        "    qml.Hadamard(wires=0)\n",
        "    qml.CNOT(wires=[0, 1])\n",
        "\n",
        "    # Thermal Interaction (The \"Leak\")\n",
        "    prob = thermal_depolarizing_channel(T)\n",
        "    qml.DepolarizingChannel(prob, wires=0)\n",
        "    qml.DepolarizingChannel(prob, wires=1)\n",
        "\n",
        "    return qml.density_matrix(wires=[0, 1])\n",
        "\n",
        "# 3. Execution & Audit Log\n",
