        "                qml.CNOT(wires=[2, 3])\n",
        "            elif gate_type == 'CZ':\n",
        "                qml.CZ(wires=[0, 3])\n",
        "                qml.CZ(wires=[2, 3])\n",
        "            elif gate_type == 'Hybrid':\n",
        "                qml.CNOT(wires=[0, 3])\n",
        "                qml.CZ(wires=[1, 3])\n",
        "\n",
        "            for i in range(4):\n",
