        "        # We now use 2 qubits (atoms) and 2 classical bits for measurement\n",
        "        qc = QuantumCircuit(2, 2)\n",
        "\n",
        "        # 1. Put Atom A into a fuzzy superposition\n",
        "        qc.h(0)\n",
        "\n",
        "        # 2. Entangle Atom A and Atom B (This is the bridge!)\n",
        "        # This forces Atom B to perfectly mimic Atom A's final state\n",
        "        qc.cx(0, 1)\n",
        "\n",
        "        # 3. Observe both atoms\n",
        "        qc.measure([0, 1], [0, 1])\n"
